in range (for a ranged attack). Roll an attack roll using the attack modifier for the weapon or unarmed attack you're using, and compare the result to the target creature's AC to determine the effect.\n\n**Critical Success** You make a damage roll according to the weapon or unarmed attack and deal double damage.\n\n**Success** You make a damage roll according to the weapon or unarmed attack and deal damage.","availability":null,"requirements":null,"prerequisites":null,"content_source_id":3},"url_aliases":["https://2e.aonprd.com/Actions.aspx?ID=2306"]},{"table":"spell","id":4689,"anchor":{"id":4689,"area":null,"cast":"TWO-ACTIONS","cost":"","name":"Invisibility","rank":2,"uuid":"8105806537970817","range":"touch","rarity":"COMMON","traits":[1447,1433,1899],"defense":null,"targets":"1 creature","trigger":null,"version":"1.0","duration":"10 minutes","meta_data":{"damage":[],"source":{"url":"https://2e.aonprd.com/Spells.aspx?ID=1577","book":"Player Core","page":"339"},"foundry":{"rules":[],"is_focus":false}},"created_at":"2024-03-23T20:47:51.959949+00:00","heightened":{"data":{},"text":[{"text":"The spell lasts 1 minute, but it doesn't end if the target uses a hostile action.","amount":"(4th)"}]},"traditions":["arcane","occult"],"description":"Illusions bend light around the target, rendering it invisible. This makes it undetected to all creatures, though the creatures can attempt to find the target, making it hidden to them instead. If the target uses a hostile action, the spell ends after that hostile action is completed.","availability":null,"requirements":null,"content_source_id":3},"url_aliases":["https://2e.aonprd.com/Spells.aspx?ID=1577"]}],"sources":[{"id":1,"url":"https://paizo.com/products/btq02eoj?Pathfinder-Player-Core","name":"Player Core","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[],"group":"pathfinder-core","deprecated":null},{"id":3,"url":null,"name":"Common Core","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[],"group":"common-core","deprecated":false},{"id":16,"url":"https://paizo.com/products/btq02eav?Pathfinder-Treasure-Vault","name":"Treasure Vault","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[1],"group":"pathfinder-core","deprecated":null}],"source16_counts":{"item":1119,"trait":24,"creature":2},"scope":"Four embedded display text leaves only. Existing operations, selections, modifiers, grants, metadata siblings and saved inventory copies are preserved."}$display099$::jsonb as spec)
select 'treasure-vault-embedded-prose'::text as id,coalesce((
  (select count(*)=4 and bool_and((a.id is not null and ((to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text))-'{updated_at,search_tsv}'::text[]) is not distinct from patch->'final') is true)
    from settings cross join lateral jsonb_array_elements(spec->'patches') patches(patch) left join public.item a on a.id=(patch->>'id')::bigint)
  and (select count(*)=3 and bool_and((s.id is not null and jsonb_typeof(s.meta_data::jsonb)='object'
    and not exists(select 1 from jsonb_each(source_spec) e where to_jsonb(s)->e.key is distinct from e.value)
    and (s.id<>16 or not exists(select 1 from jsonb_each(spec->'source16_counts') e where to_jsonb(s)#>array['meta_data','counts',e.key] is distinct from e.value))) is true)
    from settings cross join lateral jsonb_array_elements(spec->'sources') source_specs(source_spec) left join public.content_source s on s.id=(source_spec->>'id')::bigint)
  and (select count(*)=4 and bool_and((case dependency->>'table'
    when 'trait' then (select (to_jsonb(d)||jsonb_build_object('uuid',d.uuid::text))-'{updated_at,search_tsv}'::text[]=dependency->'anchor' from public.trait d where id=(dependency->>'id')::bigint)
    when 'ability_block' then (select (to_jsonb(d)||jsonb_build_object('uuid',d.uuid::text))-'{updated_at,search_tsv}'::text[]=dependency->'anchor' from public.ability_block d where id=(dependency->>'id')::bigint)
    when 'spell' then (select (to_jsonb(d)||jsonb_build_object('uuid',d.uuid::text))-'{updated_at,search_tsv}'::text[]=dependency->'anchor' from public.spell d where id=(dependency->>'id')::bigint)
    else false end) is true) from settings cross join lateral jsonb_array_elements(spec->'dependencies') dependencies(dependency))
  and not exists(select 1 from public.content_update u where upper(btrim(coalesce(u.status->>'state','PENDING'))) not in ('APPROVED','REJECTED') and (
    (u.type='content-source' and exists(select 1 from jsonb_array_elements(spec->'sources') s where u.ref_id=(s->>'id')::bigint or u.data->>'id'=s->>'id' or lower(btrim(u.data->>'name'))=lower(btrim(s->>'name')) or (s->>'url' is not null and (lower(btrim(u.data->>'url'))=lower(btrim(s->>'url')) or lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(s->>'url'))))))
    or (u.type='item' and exists(select 1 from jsonb_array_elements(spec->'patches') p where u.ref_id=(p->>'id')::bigint or u.data->>'id'=p->>'id' or u.data->>'uuid'=p#>>'{anchor,uuid}' or exists(select 1 from jsonb_array_elements_text(p->'url_aliases') url where lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(url))) or ((u.content_source_id=(p#>>'{anchor,content_source_id}')::bigint or u.data->>'content_source_id'=p#>>'{anchor,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(p#>>'{anchor,name}')))))
    or exists(select 1 from jsonb_array_elements(spec->'dependencies') d where (u.type=replace(d->>'table','_','-') or (d->>'table'='ability_block' and u.type=d#>>'{anchor,type}')) and (u.ref_id=(d->>'id')::bigint or u.data->>'id'=d->>'id' or u.data->>'uuid'=d#>>'{anchor,uuid}' or exists(select 1 from jsonb_array_elements_text(d->'url_aliases') url where lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(url))) or ((u.content_source_id=(d#>>'{anchor,content_source_id}')::bigint or u.data->>'content_source_id'=d#>>'{anchor,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(d#>>'{anchor,name}')))))
  ))
),false) as passed from settings
)
select original_checks.id,case when coalesce((status.value->>'recognized')::boolean,true) then coalesce((status.value->>'passed')::boolean,false) else original_checks.passed end as passed from original_checks cross join terminal_status status;
